"""A static review of actual native framebuffer captures, served by existing preview."""
from pathlib import Path
html='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ linh · 0.45</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#1b2421;color:#e0dcc7;font:16px/1.5 system-ui}main{max-width:1328px;margin:auto;padding:24px}h1{font:34px Georgia;margin:0 0 10px}h2{font:25px Georgia;margin:32px 0 14px}p{color:#b5bdac;max-width:950px}img{display:block;width:100%;height:auto;border:1px solid #536254}a{color:#cad8b4}button,select,input{font:inherit;accent-color:#c1d397}button,select{background:#344338;color:#ece5c8;border:1px solid #70816a;padding:8px 16px;border-radius:3px}nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:16px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0}figcaption{padding:9px 0;color:#b5bdac}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:27px}}
</style><main><h1>Cổ linh · Hình thể & thi triển</h1><p>Bốn Cổ đang chơi được có hình sinh vật riêng, dùng cùng một ảnh trên thanh kỹ năng, hành trang và Bảng Cổ. Ảnh dưới đây chụp trực tiếp từ Godot; nguồn vẽ là SVG, hiệu ứng là nét vector trong canvas.</p><img src="gu45_icons.png" alt="Bốn Cổ, minh họa lớn và kích thước thanh kỹ năng"><h2>Tụ khí → phóng → tiếp xúc</h2><p>Nguyệt Quang tụ ở bàn tay đến 0,2176 giây khi dùng kiếm. Băng Tằm phóng sau 0,08 giây. Cả hai tiếp xúc ở 0,28 giây như nhịp combat hiện tại. Bạch Ngọc mở từng mảnh giáp; Bạch Hạc để lại nét cánh và vệt gió ngắn.</p><nav><button id="play">Tạm dừng</button><label>Nhịp <select id="speed"><option value="1">1×</option><option value=".5">0,5×</option><option value=".25">0,25×</option></select></label><input type="range" id="frame" min="0" max="31" value="0"><span id="readout">1 / 32</span></nav><img id="motion" src="gu45_fx/frame000.png" alt="Chuỗi 32 khung hiệu ứng native"><details><summary>Xem 5 nhịp tĩnh</summary><img src="gu45_fx_board.png" alt="Năm nhịp hiệu ứng"></details><h2>Trong game · phím 1–4</h2><div class="grid">'''
for kind,name in [('moon','Nguyệt Quang'),('shield','Bạch Ngọc'),('dash','Bạch Hạc'),('frost','Băng Tằm')]:
    html+=f'<figure><img src="gu45_world_{kind}_contact.png" alt="{name} trong game"><figcaption>{name} · input kỹ năng thật trong Godot</figcaption></figure>'
html+='''</div><h2>Bảng Cổ</h2><img src="gu45_gu_board.png" alt="Bảng Cổ với minh họa sinh vật"><p>Giữ nguyên bốn ID Cổ, chỉ số chiến đấu, lưu game, đồng hồ sát thương và thao tác nâng cấp/hợp thành. Đây là lượt nâng hình và hiệu ứng.</p></main><script>
const picture=document.querySelector('#motion'),range=document.querySelector('#frame'),button=document.querySelector('#play'),readout=document.querySelector('#readout'),speed=document.querySelector('#speed');let playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,index=0,previous=performance.now(),elapsed=0;const frames=Array.from({length:32},(_,i)=>{let image=new Image;image.src='gu45_fx/frame'+String(i).padStart(3,'0')+'.png';return image});function paint(){picture.src=frames[index].src;range.value=index;readout.textContent=(index+1)+' / 32';button.textContent=playing?'Tạm dừng':'Phát'}button.onclick=()=>{playing=!playing;elapsed=index*20.645;paint()};range.oninput=()=>{playing=false;index=+range.value;paint()};function tick(now){if(playing){elapsed+=(now-previous)*Number(speed.value);const next=Math.floor(elapsed/20.645)%32;if(next!==index){index=next;paint()}}previous=now;requestAnimationFrame(tick)}paint();requestAnimationFrame(tick);
</script></html>'''
Path('artifacts/gu45_review.html').write_text(html,encoding='utf-8')
